const SHELL='watchnext-shell-v36',IMAGES='watchnext-images-v1';
self.addEventListener('install',event=>{event.waitUntil(caches.open(SHELL).then(cache=>cache.addAll(['./','./index.html','./style.css','./appearance.css','./appearance.js','./glass-tabs.js','./app.js?v=logo-align-23','./core.js','./settings.js','./artwork.js','./discover.js','./wishlist.js','./explore.js','./preload.js','./suggestions.js','./integrations.js','./release-search.js','./navigation.js','./icon.svg','./logo.svg','./logo-light.svg','./icon-light.svg','./icon-192.png','./manifest.webmanifest'])));self.skipWaiting();});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('watchnext-')&&![SHELL,IMAGES].includes(k)).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',event=>{const request=event.request,url=new URL(request.url);if(request.method!=='GET'||url.pathname.startsWith('/api/')||url.pathname.endsWith('/web-config'))return;if(request.destination==='image'){event.respondWith(caches.open(IMAGES).then(async cache=>{const cached=await cache.match(request);if(cached)return cached;const response=await fetch(request);if(response.ok||response.type==='opaque'){cache.put(request,response.clone());const keys=await cache.keys();if(keys.length>80)cache.delete(keys[0]);}return response;}));return;}if(url.origin===location.origin&&['document','script','style','manifest'].includes(request.destination)){event.respondWith(fetch(request).then(response=>{if(response.ok&&!response.redirected){const copy=response.clone();caches.open(SHELL).then(cache=>cache.put(request,copy));}return response;}).catch(async()=>await caches.match(request)||(request.mode==='navigate'?await caches.match('./index.html'):Response.error())));}});
